typedef long long ll;

int cmp_desc_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int cmp_asc_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int X, Y, A, B, C;
    if (scanf("%d %d %d %d %d", &X, &Y, &A, &B, &C) != 5) return 0;

    ll *p = (ll *)malloc(sizeof(ll) * A);
    ll *q = (ll *)malloc(sizeof(ll) * B);
    ll *r = (ll *)malloc(sizeof(ll) * C);

    for (int i = 0; i < A; i++) scanf("%lld", &p[i]);
    for (int i = 0; i < B; i++) scanf("%lld", &q[i]);
    for (int i = 0; i < C; i++) scanf("%lld", &r[i]);

    qsort(p, A, sizeof(ll), cmp_desc_ll);
    qsort(q, B, sizeof(ll), cmp_desc_ll);
    qsort(r, C, sizeof(ll), cmp_desc_ll);

    int n = X + Y;
    ll *cand = (ll *)malloc(sizeof(ll) * n);

    int idx = 0;
    for (int i = 0; i < X; i++) cand[idx++] = p[i];
    for (int i = 0; i < Y; i++) cand[idx++] = q[i];

    qsort(cand, n, sizeof(ll), cmp_asc_ll);

    int ptr = 0;
    for (int i = 0; i < C && ptr < n; i++) {
        if (r[i] > cand[ptr]) {
            cand[ptr] = r[i];
            ptr++;
        } else {
            break;
        }
    }

    ll ans = 0;
    for (int i = 0; i < n; i++) ans += cand[i];

    printf("%lld\n", ans);

    free(p);
    free(q);
    free(r);
    free(cand);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp_desc(const void *a, const void *b) {
    long long x = *(long long*)a, y = *(long long*)b;
    if (y > x) return 1;
    if (y < x) return -1;
    return 0;
}

int main() {
    long long X, Y, A, B, C;
    scanf("%lld %lld", &X, &Y);
    scanf("%lld %lld %lld", &A, &B, &C);
    long long p[A+1], q[B+1], r[C+1];
    for (int i = 0; i < A; i++) scanf("%lld", &p[i]);
    for (int i = 0; i < B; i++) scanf("%lld", &q[i]);
    for (int i = 0; i < C; i++) scanf("%lld", &r[i]);
    qsort(p, A, sizeof(long long), cmp_desc);
    qsort(q, B, sizeof(long long), cmp_desc);
    qsort(r, C, sizeof(long long), cmp_desc);

    // prefix sums
    long long sp[A+1], sq[B+1], sr[C+1];
    sp[0] = sq[0] = sr[0] = 0;
    for (int i = 0; i < A; i++) sp[i+1] = sp[i] + p[i];
    for (int i = 0; i < B; i++) sq[i+1] = sq[i] + q[i];
    for (int i = 0; i < C; i++) sr[i+1] = sr[i] + r[i];

    // Try all splits: use k colorless for red (need max(0,X-A) <= k <= min(C, X))
    // then C-k for green, need max(0,Y-B) <= C-k <= min(C,Y)
    long long ans = -1e18;
    long long kmin = (X > A) ? X - A : 0;
    long long kmax = (X < C) ? X : C; if (kmax > X) kmax = X;
    for (long long k = kmin; k <= kmax; k++) {
        long long rem = C - k;
        if (rem < ((Y > B) ? Y - B : 0)) continue;
        if (rem > Y) continue;
        long long val = sp[A < X-k ? A : X-k] + sr[k] - (k > 0 ? 0 : 0);
        // red: top (X-k) from p, top k from r... but r is shared!
        // This approach doesn't work directly since r is shared
        break;
    }
    // Need different approach - iterate over how many colorless go to red
    // For each split k (colorless to red), greedily pick best
    // But we need top k of r for red and top (used_green) of remaining r for green
    // Since r is sorted, top k for red are r[0..k-1], top j for green from remaining are r[k..k+j-1]
    ans = -1e18;
    for (long long k = kmin; k <= kmax; k++) {
        long long j_need = (Y > B) ? Y - B : 0;
        long long j_max = Y < C - k ? Y : C - k;
        if (j_need > C - k) continue;
        // best j: use as many colorless for green as beneficial
        // red sum: top min(A,X-k) from p + top k from r[0..k-1]... wait r is shared
        // r[0..k-1] go to red, r[k..k+j-1] go to green
        long long red_from_p = (A < X - k) ? A : X - k;
        long long red_sum = sp[red_from_p] + sr[k] - sr[0]; // sr[k] = sum of r[0..k-1]
        // Hmm sr[k] = r[0]+...+r[k-1], that's sum of first k colorless for red
        long long green_from_q = (B < Y) ? B : Y;
        // We need Y green total: green_from_q from q, rest from colorless
        // colorless for green: j = Y - green_from_q, but these come from r[k..]
        long long j = Y - green_from_q;
        if (j < 0) j = 0;
        if (j > C - k) continue;
        long long green_sum = sq[green_from_q] + (sr[k + j] - sr[k]);
        long long total = red_sum + green_sum;
        if (total > ans) ans = total;
    }
    printf("%lld\n", ans);
    return 0;
}

