public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int X = fs.nextInt();
        int Y = fs.nextInt();
        int A = fs.nextInt();
        int B = fs.nextInt();
        int C = fs.nextInt();

        Long[] p = new Long[A];
        Long[] q = new Long[B];
        Long[] r = new Long[C];

        for (int i = 0; i < A; i++) p[i] = fs.nextLong();
        for (int i = 0; i < B; i++) q[i] = fs.nextLong();
        for (int i = 0; i < C; i++) r[i] = fs.nextLong();

        Arrays.sort(p, Collections.reverseOrder());
        Arrays.sort(q, Collections.reverseOrder());
        Arrays.sort(r, Collections.reverseOrder());

        ArrayList<Long> candidates = new ArrayList<>();

        for (int i = 0; i < X; i++) candidates.add(p[i]);
        for (int i = 0; i < Y; i++) candidates.add(q[i]);
        for (int i = 0; i < C; i++) candidates.add(r[i]);

        candidates.sort(Collections.reverseOrder());

        long ans = 0;
        for (int i = 0; i < X + Y; i++) ans += candidates.get(i);

        System.out.println(ans);
    }
}

